```yaml
name: Gemini Code Review

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  contents: read
  pull-requests: write

jobs:
  gemini-review:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Get PR diff
        id: diff
        run: |
          git diff ${{ github.event.pull_request.base.sha }} ${{ github.event.pull_request.head.sha }} > pr.diff
          echo "diff_size=$(wc -c < pr.diff)" >> $GITHUB_OUTPUT

      - name: Review with Gemini
        if: steps.diff.outputs.diff_size > 0
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const diff = fs.readFileSync('pr.diff', 'utf8');

            // Truncate diff if too large for API limits (approx 100k chars)
            const maxChars = 100000;
            const truncatedDiff = diff.length > maxChars ? diff.substring(0, maxChars) + "\n... (truncated)" : diff;

            const prompt = `You are an expert Rust developer reviewing a pull request.
            Please review the changes in the provided diff.
            Focus on:
            1. Correctness and potential bugs
            2. Performance implications
            3. Idiomatic Rust usage
            4. Security concerns
            5. Code style and readability

            Provide concise, actionable feedback.
            If the code looks good, say so briefly.
            If there are issues, list them clearly with line references if possible.

            Diff:
            \`\`\`diff
            ${truncatedDiff}
            \`\`\``;

            const response = await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'x-goog-api-key': process.env.GEMINI_API_KEY
              },
              body: JSON.stringify({
                contents: [{
                  parts: [{
                    text: prompt
                  }]
                }]
              })
            });

            if (!response.ok) {
              const errorText = await response.text();
              core.error(`Gemini API error: ${response.status} ${errorText}`);
              return;
            }

            const data = await response.json();

            if (data.error) {
              core.error(`Gemini API error: ${JSON.stringify(data.error)}`);
              return;
            }

            const reviewText = data.candidates?.[0]?.content?.parts?.[0]?.text || "No review generated.";

            // Post comment to PR
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `## Gemini Code Review\n\n${reviewText}`
            });
        env:
          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}
```

